import type { Word, WordPart, MorphemeType, Reliability, Meaning, Example, ExamLevel } from '@/types/domain';

function p(
  text: string,
  type: MorphemeType,
  meaning: string,
  morphemeId?: string,
  reliability: Reliability = 'etymological',
  isInferred = false,
): WordPart {
  return { text, type, meaning, morphemeId, reliability, isInferred };
}

function mk(o: {
  id: string;
  word: string;
  phonetic: string;
  meanings: Meaning[];
  parts: WordPart[];
  rootIds: string[];
  prefixIds?: string[];
  suffixIds?: string[];
  etymology: string;
  evolution?: string[];
  examples: Example[];
  difficulty?: 1 | 2 | 3 | 4 | 5;
  frequency?: number;
  examLevels?: ExamLevel[];
  mnemonic?: string;
}): Word {
  return {
    id: o.id,
    word: o.word,
    phonetic: o.phonetic,
    meanings: o.meanings,
    parts: o.parts,
    etymParts: undefined,
    rootIds: o.rootIds,
    prefixIds: o.prefixIds ?? [],
    suffixIds: o.suffixIds ?? [],
    etymology: o.etymology,
    evolution: o.evolution,
    examples: o.examples,
    difficulty: o.difficulty ?? 2,
    frequency: o.frequency ?? 50,
    examLevels: o.examLevels ?? ['日常'],
    mnemonic: o.mnemonic,
  };
}

